Here is the root cause:
The bug was caused by requiring the global `struct_mutex` for exclusive access to the temporary `dfs_link` inside the `i915_dependency`, which led to high contention and potential performance issues as not all callers needed to hold this highly contended lock. This forced unnecessary locking on operations that could be handled with a more localized locking mechanism.

Here is the patch:

 static void execlists_schedule(struct drm_i915_gem_request *request, int prio)
 {
+	static DEFINE_MUTEX(lock);
 	struct intel_engine_cs *engine = NULL;
 	struct i915_dependency *dep, *p;
 	struct i915_dependency stack;
 	LIST_HEAD(dfs);

 	if (prio <= READ_ONCE(request->priotree.priority))
 		return;

-	/* Need BKL in order to use the temporary link inside i915_dependency */
-	lockdep_assert_held(&request->i915->drm.struct_mutex);
+	/* Need global lock to use the temporary link inside i915_dependency */
+	mutex_lock(&lock);

 	stack.signaler = &request->priotree;
 	list_add(&stack.dfs_link, &dfs);

 	/* Recursively bump all dependent priorities to match the new request.
 	 *
 	 * A naive approach would be to use recursion:
 	 * static void update_priorities(struct i915_priotree *pt, prio) {
 	 *	list_for_each_entry(dep, &pt->signalers_list, signal_link)
 	 *		update_priorities(dep->signal, prio)
 	 *	insert_request(pt);
 	 * }
 	 * but that may have unlimited recursion depth and so runs a very
 	 * real risk of overunning the kernel stack. Instead, we build
 	 * a flat list of all dependencies starting with the current request.
 	 * As we walk the list of dependencies, we add all of its dependencies
 	 * to the end of the list (this may include an already visited
 	 * request) and continue to walk onwards onto the new dependencies. The
 	 * end result is a topological list of requests in reverse order, the
 	 * last element in the list is the request we must execute first.
 	 */
 	list_for_each_entry_safe(dep, p, &dfs, dfs_link) {
 		struct i915_priotree *pt = dep->signaler;

 		list_for_each_entry(p, &pt->signalers_list, signal_link)
 			if (prio > READ_ONCE(p->signaler->priority))
 				list_move_tail(&p->dfs_link, &dfs);

 		p = list_next_entry(dep, dfs_link);
 		if (!RB_EMPTY_NODE(&pt->node))
 			continue;

 		engine = pt_lock_engine(pt, engine);

 		/* If it is not already in the rbtree, we can update the
 		 * priority inplace and skip over it (and its dependencies)
 		 * if it is referenced *again* as we descend the dfs.
 		 */
 		if (prio > pt->priority && RB_EMPTY_NODE(&pt->node)) {
 			pt->priority = prio;
 			list_del_init(&dep->dfs_link);
 		}
 	}

 	/* Fifo and depth-first replacement ensure our deps execute before us */
 	list_for_each_entry_safe_reverse(dep, p, &dfs, dfs_link) {
 		struct i915_priotree *pt = dep->signaler;

 		INIT_LIST_HEAD(&dep->dfs_link);

 		engine = pt_lock_engine(pt, engine);

 		if (prio <= pt->priority)
 			continue;

 		GEM_BUG_ON(RB_EMPTY_NODE(&pt->node));

 		pt->priority = prio;
 		rb_erase(&pt->node, &engine->execlist_queue);
 		if (insert_request(pt, &engine->execlist_queue))
 			engine->execlist_first = &pt->node;
 	}

 	if (engine)
 		spin_unlock_irq(&engine->timeline->lock);

+	mutex_unlock(&lock);
+
 	/* XXX Do we need to preempt to make room for us and our deps? */
 }



